from pathlib import Path
import json,re
R=Path.cwd();D=R/'runtime/basic-closeout-20261017';v=json.loads((D/'basic-inventory-r19.json').read_text(encoding='utf8'));rows=v['basic_nodes'];named=lambda pred:[x for x in rows if x['path'] and pred(x['path'])]
columns=named(lambda p:len(p)==2 and p[0]=='STRUCTURE_EXISTING' and p[-1].startswith('COLUMN_'))
