summary={'status':'PRESENT_WITH_PRIOR_NATIVE_SELECTED_CONNECTION_EVIDENCE','revision':19,'geometry_writes':0,'basis':'Actual native inventory plus prior same-case door/landing/glass/step/support probes. Counts indicate presence, not count-only acceptance or full-route/source certification.','columns':{'count':len(columns),'nodes':columns},'partition_wall_groups':{'count':len(walls),'nodes':walls},'spiral_stair_assemblies':{'count':len(spirals),'nodes':spirals},'door_portal_named_groups':{'count':len(doorassemblies),'paths':[x['path'] for x in doorassemblies]},'glass_window_named_groups':{'count':len(windows),'paths':[x['path'] for x in windows]},'end_stair_related_named_groups':endstairs,'existing_native_evidence':[{'report':'../2026-10-16-customer-readiness-r11-enclosure/README.md','selected_check':'real lower-end/top-hall enclosure and actual entrance portals'},{'report':'../2026-10-16-customer-readiness-r12-door-clearance/README.md','selected_check':'actual sliding-door/adjacent-gallery clearance'},{'report':'../2026-10-16-customer-readiness-r13-circulation-mesh/README.md','selected_check':'actual remote stairs, landing arrival/clearance and protected ramp body'},{'report':'../2026-10-16-customer-readiness-r14-facades/README.md','selected_check':'actual lower layered doors/windows, room recesses and frames'},{'report':'../2026-10-17-r19-basic-building-closeout/native/r19-interior-finish-probe.json','selected_check':'current216treadroot/18landingcontact/216headroom samples'}],'owner_final_scope':'Basic [REDACTED_AUTH] surroundings only, then close this case. No more fine-detail/circular-hole/curtain/beam changes.'}
assert len(columns)>=30 and len(walls)==18 and len(spirals)==3 and len(doorassemblies)>0 and len(windows)>0
(D/'basic-building-summary-r19.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf8');print(json.dumps({k:summary[k]['count'] for k in ['columns','partition_wall_groups','spiral_stair_assemblies','door_portal_named_groups','glass_window_named_groups']}))
